#!/usr/bin/env python3
"""Incremental personal-data inventory scanner.

Walks target/ for .json schema files, classifies field names against inline
rules, and writes inventory.json. A content-hash cache (keyed by path +
sha256) ensures unchanged files are never re-parsed on subsequent runs.

Instrumentation: every invocation of the real parser increments a counter;
at the end of a run the counter is reset and persisted to scan_stats.json,
so each run reports exactly how many files it parsed.
"""

from __future__ import annotations

import hashlib
import json
import sys
from pathlib import Path

TARGET_DIR = "target"
INVENTORY_FILE = "inventory.json"
STATS_FILE = "scan_stats.json"

# Inline classification rules: substring in field name -> category.
RULES = [
    ("email", "contact"),
    ("phone", "contact"),
    ("name", "identity"),
    ("dob", "identity"),
]

UNCLASSIFIED = "unclassified"


# ---------------------------------------------------------------------------
# Parser + instrumentation
# ---------------------------------------------------------------------------

_parse_count = 0


def classify_field(field_name: str) -> str:
    lowered = field_name.lower()
    for needle, category in RULES:
        if needle in lowered:
            return category
    return UNCLASSIFIED


def parse_schema_text(text: str) -> dict[str, str]:
    """Parse one schema file body into {field_name: category}.

    This is THE expensive function; every call is counted.
    """
    global _parse_count
    _parse_count += 1
    data = json.loads(text)
    fields: dict[str, str] = {}

    def walk(node) -> None:
        if isinstance(node, dict):
            for key, value in node.items():
                if key == "fields" and isinstance(value, dict):
                    for fname in value:
                        fields[str(fname)] = classify_field(str(fname))
                else:
                    walk(value)
        elif isinstance(node, list):
            for item in node:
                walk(item)

    walk(data)
    return dict(sorted(fields.items()))


# ---------------------------------------------------------------------------
# Scanner
# ---------------------------------------------------------------------------

def sha256_of(content: bytes) -> str:
    return hashlib.sha256(content).hexdigest()


def load_json(path: Path, default):
    if not path.exists():
        return default
    try:
        return json.loads(path.read_text(encoding="utf-8"))
    except (json.JSONDecodeError, OSError):
        return default


def scan(target_dir: Path | None = None, out_dir: Path | None = None) -> dict:
    """Run one incremental scan. Returns the run's stats."""
    global _parse_count
    target_dir = Path(target_dir) if target_dir else Path(TARGET_DIR)
    out_dir = Path(out_dir) if out_dir else Path(".")
    _parse_count = 0  # per-run counter

    # Cache lives inside inventory.json: path -> {"sha256": ..., "fields": ...}
    inventory: dict = load_json(out_dir / INVENTORY_FILE, {})
    cache = inventory.get("_cache", {})

    # Discover current schema files (sorted for determinism).
    current: dict[str, bytes] = {}
    if target_dir.exists():
        for p in sorted(target_dir.rglob("*.json")):
            rel = p.relative_to(target_dir).as_posix()
            current[rel] = p.read_bytes()

    new_inventory: dict = {"_cache": {}, "files": {}}

    for rel, raw in current.items():
        digest = sha256_of(raw)
        cached = cache.get(rel)
        if cached and cached.get("sha256") == digest:
            # Cache hit: reuse parsed result, do NOT call the parser.
            entry_fields = cached["fields"]
        else:
            entry_fields = parse_schema_text(raw.decode("utf-8"))
        new_inventory["_cache"][rel] = {"sha256": digest}
        new_inventory["files"][rel] = {"fields": entry_fields}

    new_inventory["_cache"] = {
        rel: {"sha256": info["sha256"], "fields": new_inventory["files"][rel]["fields"]}
        for rel, info in new_inventory["_cache"].items()
    }

    (out_dir / INVENTORY_FILE).write_text(
        json.dumps(new_inventory, indent=2, sort_keys=True), encoding="utf-8"
    )

    stats = {"parsed": _parse_count, "scanned": len(current)}
    (out_dir / STATS_FILE).write_text(json.dumps(stats, indent=2), encoding="utf-8")
    return stats


def main(argv: list[str]) -> int:
    target = Path(argv[1]) if len(argv) > 1 else Path(TARGET_DIR)
    stats = scan(target)
    print(json.dumps(stats))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

