#!/usr/bin/env python3
"""Deterministic generator for the 6-file test tree under target/."""

from __future__ import annotations

import json
from pathlib import Path


def schema(*fields: str, table: str = "t") -> dict:
    return {"table": table, "fields": {f: {"type": "string"} for f in fields}}


SCHEMAS: dict[str, dict] = {
    "users/users.schema.json": schema(
        "email", "phone_number", "full_name", "date_of_birth",
        table="users",
    ),
    "users/prefs.schema.json": schema("theme", "locale", table="prefs"),
    "billing/accounts.schema.json": schema(
        "account_name", "contact_email", "billing_phone", table="accounts",
    ),
    "billing/invoices.schema.json": schema(
        "invoice_id", "amount_due", "due_date", table="invoices",
    ),
    "hr/employees.schema.json": schema(
        "employee_dob", "work_email", "emergency_contact_phone", table="employees",
    ),
    "logs/events.schema.json": schema(
        "event_type", "session_id", "created_at", table="events",
    ),
}


def build_tree(base: Path) -> list[Path]:
    """Create the 6-file tree under base/target/. Returns paths written."""
    written: list[Path] = []
    target = base / "target"
    for rel, doc in SCHEMAS.items():
        p = target / rel
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_text(json.dumps(doc, indent=2) + "\n", encoding="utf-8")
        written.append(p)
    return written


if __name__ == "__main__":
    import sys

    root = Path(sys.argv[1]) if len(sys.argv) > 1 else Path(".")
    for p in build_tree(root):
        print(p)

